static int32_t n1s() { return contact.ground_n1[0]; }
static int32_t n1c() { return contact.ground_n1[1]; }
static int32_t n2s() { return contact.ground_n2[0]; }
static int32_t n2c() { return contact.ground_n2[1]; }

