void Car::ground_contact(CarVertex &v, uint16_t index)
{
    int32_t vn = mulq31(mulq31(v.vel.z, n1c()), n2c())
               - mulq31(v.vel.x, n1s())
               - mulq31(v.vel.y, n2s());
