std::vector<EclOpcodeSpec> minimal_vm_opcodes(EclImageDialect images, EclAreaDialect area, EclPartyDialect party,
    EclPartyCheckDialect check, EclSurpriseDialect surprise, EclEncounterDialect encounter, EclMonsterDialect monsters) {
    require(monsters == EclMonsterDialect::disabled || monsters == EclMonsterDialect::setup_v1,"Unknown monster dialect");
    require(encounter == EclEncounterDialect::disabled || encounter == EclEncounterDialect::menu14,
        "Unknown encounter dialect");
    require(surprise == EclSurpriseDialect::disabled || surprise == EclSurpriseDialect::signed_threshold2,
        "Unknown surprise dialect");
    require(check == EclPartyCheckDialect::disabled || check == EclPartyCheckDialect::class_presence2,
        "Unknown party check dialect");
    require(images == EclImageDialect::disabled || images == EclImageDialect::sprite3,"Unknown image dialect");
    require(area == EclAreaDialect::disabled || area == EclAreaDialect::map3,"Unknown area dialect");
    require(party == EclPartyDialect::disabled || party == EclPartyDialect::load_character ||
        party == EclPartyDialect::weighted_strength,"Unknown party dialect");
    auto result = routing_ecl_opcodes();
    result.push_back({0x15, "MENU_VERTICAL", 3, 2});
    result.push_back({0x2b, "MENU_HORIZONTAL", 2, 1});
    result.push_back({0x24, "COMBAT", 0});
    result.push_back({0x2a, "COPY_MEM", 3});
    result.push_back({0x2d, "CALL_HOST", 1});
    result.push_back({0x20, "NEW_ECL", 1});
    result.push_back({0x3a, "DELAY", 0});
    if (images == EclImageDialect::sprite3) {
        result.push_back({0x0c,"SPRITE_START3",3});
        result.push_back({0x31,"SPRITE_OFF",0});
        result.push_back({0x37,"LOAD_AREA_DECO",3});
    }
    if (area == EclAreaDialect::map3) result.push_back({0x21,"LOAD_AREA_MAP",3});
    if (party == EclPartyDialect::disabled)
        std::erase_if(result,[](const auto& op) { return op.opcode == 0x0a; });
    else result.push_back({0x39,"WHO",1});
    if (party == EclPartyDialect::weighted_strength) result.push_back({0x1d,"PARTY_STRENGTH",1});
    if (check == EclPartyCheckDialect::class_presence2) result.push_back({0x22,"PARTY_CLASS_CHECK2",2});
    if (surprise == EclSurpriseDialect::signed_threshold2) result.push_back({0x23,"SURPRISE_THRESHOLD2",4});
    if (encounter == EclEncounterDialect::menu14) result.push_back({0x29,"ENCOUNTER_MENU14",14});
    if (monsters == EclMonsterDialect::setup_v1) result.push_back({0x1c,"CLEAR_MON",0});
    return result;
}

EclExecution execute_ecl(std::span<const std::uint8_t> record, EclEventKind kind,
    const EclDispatchDialect& dialect, std::span<const EclOpcodeSpec> opcodes,
    EclState& state, EclHost& host, EclLimits limits, EclRandomDialect random, EclArithmeticDialect arithmetic,
    std::optional<EclSurpriseBinding> surprise, std::optional<EclEncounterBinding> encounter, EclMonsterDialect monsters) {
    EclExecution result;
    try {
        require(monsters == EclMonsterDialect::disabled || monsters == EclMonsterDialect::setup_v1,"Unknown monster dialect");
        if (monsters == EclMonsterDialect::setup_v1) for (const auto opcode : {0x0b,0x1c}) {
            const auto spec = std::find_if(opcodes.begin(),opcodes.end(),[opcode](const auto& op) { return op.opcode == opcode; });
            require(spec != opcodes.end() && spec->operand_count == (opcode == 0x0b ? 3 : 0) &&
                spec->variable_count_operand == -1 && spec->mnemonic == (opcode == 0x0b ? "LOAD_MON" : "CLEAR_MON") &&
                std::count_if(opcodes.begin(),opcodes.end(),[opcode](const auto& op) { return op.opcode == opcode; }) == 1,
                "Conflicting monster opcode definition");
        }
        const auto encounter_spec = std::find_if(opcodes.begin(),opcodes.end(),[](const auto& op) { return op.opcode == 0x29; });
        if (encounter) require(encounter->dialect == EclEncounterDialect::menu14 &&
            encounter->distance_addresses[0] != encounter->distance_addresses[1] &&
            encounter->view_mode_address != encounter->distance_addresses[0] &&
            encounter->view_mode_address != encounter->distance_addresses[1],"Invalid encounter binding");
        if (encounter || encounter_spec != opcodes.end()) require(encounter && encounter_spec != opcodes.end() &&
            encounter_spec->operand_count == 14 && encounter_spec->variable_count_operand == -1 &&
            encounter_spec->mnemonic == "ENCOUNTER_MENU14" &&
            std::count_if(opcodes.begin(),opcodes.end(),[](const auto& op) { return op.opcode == 0x29; }) == 1,
            "Conflicting encounter opcode definition or missing adapter");
        const auto surprise_spec = std::find_if(opcodes.begin(),opcodes.end(),[](const auto& op) { return op.opcode == 0x23; });
        if (surprise) require(surprise->dialect == EclSurpriseDialect::signed_threshold2,
            "Unknown surprise dialect");
        if (surprise || surprise_spec != opcodes.end()) require(surprise && surprise_spec != opcodes.end() &&
            surprise_spec->operand_count == 4 && surprise_spec->variable_count_operand == -1 &&
            surprise_spec->mnemonic == "SURPRISE_THRESHOLD2" &&
            std::count_if(opcodes.begin(),opcodes.end(),[](const auto& op) { return op.opcode == 0x23; }) == 1,
            "Conflicting surprise opcode definition or missing adapter");
        require(arithmetic == EclArithmeticDialect::disabled || arithmetic == EclArithmeticDialect::unsigned16,
            "Unknown arithmetic dialect");
        if (arithmetic == EclArithmeticDialect::unsigned16)
            for (const auto opcode : {5,6,7}) {
                const auto spec = std::find_if(opcodes.begin(),opcodes.end(),
                    [opcode](const auto& op) { return op.opcode == opcode; });
                require(spec != opcodes.end() && spec->operand_count == 3 && spec->variable_count_operand == -1 &&
                    std::count_if(opcodes.begin(),opcodes.end(),[opcode](const auto& op) { return op.opcode == opcode; }) == 1,
                    "Conflicting arithmetic opcode definition");
            }
        require(random == EclRandomDialect::disabled || random == EclRandomDialect::byte_upper,
            "Unknown ECL random dialect");
        const auto image_spec = std::find_if(opcodes.begin(),opcodes.end(),[](const auto& op) { return op.opcode == 0x0c; });
        const bool images_enabled = image_spec != opcodes.end();
        const auto party_spec = std::find_if(opcodes.begin(),opcodes.end(),[](const auto& op) { return op.opcode == 0x0a; });
        if (party_spec != opcodes.end()) require(party_spec->operand_count == 1 && party_spec->variable_count_operand == -1 &&
            std::count_if(opcodes.begin(),opcodes.end(),[](const auto& op) { return op.opcode == 0x0a; }) == 1,
            "Conflicting VM party opcode definition");
        const auto who_spec = std::find_if(opcodes.begin(),opcodes.end(),[](const auto& op) { return op.opcode == 0x39; });
        const auto class_check = std::find_if(opcodes.begin(),opcodes.end(),[](const auto& op) { return op.opcode == 0x22; });
        if (class_check != opcodes.end()) require(class_check->operand_count == 2 &&
            class_check->variable_count_operand == -1 && class_check->mnemonic == "PARTY_CLASS_CHECK2" &&
            std::count_if(opcodes.begin(),opcodes.end(),[](const auto& op) { return op.opcode == 0x22; }) == 1,
            "Conflicting party check opcode definition");
        const auto strength_spec = std::find_if(opcodes.begin(),opcodes.end(),[](const auto& op) { return op.opcode == 0x1d; });
        if (strength_spec != opcodes.end()) require(strength_spec->operand_count == 1 &&
            strength_spec->variable_count_operand == -1 &&
            std::count_if(opcodes.begin(),opcodes.end(),[](const auto& op) { return op.opcode == 0x1d; }) == 1,
            "Conflicting VM party strength opcode definition");
        if (who_spec != opcodes.end()) require(who_spec->operand_count == 1 && who_spec->variable_count_operand == -1 &&
            std::count_if(opcodes.begin(),opcodes.end(),[](const auto& op) { return op.opcode == 0x39; }) == 1,
            "Conflicting VM WHO opcode definition");
        const auto area_spec = std::find_if(opcodes.begin(),opcodes.end(),[](const auto& op) { return op.opcode == 0x21; });
        if (area_spec != opcodes.end()) require(area_spec->operand_count == 3 && area_spec->variable_count_operand == -1 &&
            std::count_if(opcodes.begin(),opcodes.end(),[](const auto& op) { return op.opcode == 0x21; }) == 1,
            "Conflicting VM area opcode definition");
        if (images_enabled) require(image_spec->operand_count == 3 && image_spec->variable_count_operand == -1 &&
            std::count_if(opcodes.begin(),opcodes.end(),[](const auto& op) { return op.opcode == 0x0c; }) == 1,
            "Conflicting VM opcode definition");
        require(limits.steps > 0 && limits.stack_depth > 0, "ECL execution limits must be positive");
        const auto entries = decode_ecl_program_entries(record, dialect, opcodes);
        const auto code = record.subspan(entries.record_prefix_size);
        const auto numeric = [&](const EclOperand& operand) { return number(operand, state, host, code, dialect.code_base); };
        const auto store = [&](const EclOperand& operand, std::uint32_t value) {
            destination(operand, state);
            const auto end = operand.value + (operand.type == 3 ? 2u : 1u);
            require(end <= dialect.code_base || operand.value >= dialect.code_base + code.size(),
                "Self-modifying ECL program memory is unsupported");
            if (!host.write_memory(static_cast<std::uint16_t>(operand.value),value,operand.type == 3 ? 2 : 1))
                write(operand, value, state);
        };
        const auto index = static_cast<std::size_t>(kind);
        require(index < 5, "Invalid ECL lifecycle kind");
        std::size_t cursor = entries.instruction_offsets[index];
        std::vector<std::size_t> stack;
        std::map<std::size_t, std::size_t> boundaries;
        // Track decoded intervals. Branches into known operands/data fail.
        const auto decode = [&](std::size_t offset) {
            require(result.steps < limits.steps, "ECL step limit exceeded");
            ++result.steps;
            result.bytecode_offset = offset;
            const auto instruction = decode_ecl_instruction(code, offset, opcodes);
            const auto end = offset + instruction.size;
            const auto next = boundaries.lower_bound(offset);
            if (next != boundaries.end()) require(next->first == offset || end <= next->first, "Overlapping ECL instructions");
            if (next != boundaries.begin()) require(std::prev(next)->second <= offset, "ECL branch inside operand data");
            boundaries[offset] = end;
            // Decode arity from profile, but reject semantic conflicts explicitly.
            const auto expected = minimal_vm_opcodes(EclImageDialect::sprite3,EclAreaDialect::map3);
            const auto spec = std::find_if(expected.begin(), expected.end(), [&](const auto& s) { return s.opcode == instruction.opcode; });
            if (spec != expected.end()) {
                const auto actual = std::find_if(opcodes.begin(), opcodes.end(), [&](const auto& s) { return s.opcode == instruction.opcode; });
                require(actual->operand_count == spec->operand_count && actual->variable_count_operand == spec->variable_count_operand,
                    "Conflicting VM opcode definition");
            }
            return instruction;
        };
        const auto branch = [&](const EclOperand& operand) {
            require(operand.type == 1 || operand.type == 3 || operand.type == 5, "Invalid ECL branch operand");
            require(operand.value >= dialect.code_base, "ECL address below code base");
            const auto offset = static_cast<std::size_t>(operand.value - dialect.code_base);
            require(offset >= entries.header_size && offset < code.size(), "ECL branch outside code body");
            return offset;
        };
        // Comparison belongs to the invocation; flags and memory persist.
        state.comparison = 0;
        while (true) {
            const auto instruction = decode(cursor);
            cursor += instruction.size;
            const auto& args = instruction.operands;
            switch (instruction.opcode) {
            case 0: result.exited = true; return result;
            case 0x3a: host.delay(); break;
            case 0x1d:
                destination(args[0],state);
                store(args[0],host.party_strength()); break;
            case 0x22: {
                destination(args[0],state); destination(args[1],state);
                const auto present = host.party_class_present();
                store(args[0],present ? 1 : 0); store(args[1],0);
                break;
            }
            case 0x23: {
                require(surprise.has_value(),"Surprise adapter unavailable");
                require(state.random.has_value(),"RNG state unavailable; legacy saves require an explicit new seed");
                std::array<int,4> values{};
                for (std::size_t i = 0; i < values.size(); ++i) values[i] = numeric(args[i]) & 255u;
                const auto signed_byte = [](int value) {
                    const auto byte = static_cast<std::uint8_t>(value);
                    return byte < 128 ? int(byte) : int(byte)-256;
                };
                const auto first_threshold = signed_byte(values[3]+2-values[0]);
                const auto second_threshold = signed_byte(values[1]+2-values[2]);
                auto candidate = *state.random;
                const auto first = candidate.draw(6)+1;
                const auto second = candidate.draw(6)+1;
                // The native second test overwrites its earlier both-success result.
                const auto value = int(second) <= second_threshold ? 2 : int(first) <= first_threshold ? 1 : 0;
                EclOperand output{}; output.type = 1; output.value = surprise->result_address;
                store(output,value);
                state.random = candidate;
                break;
            }
            case 0x20: {
                const auto id = numeric(args[0]);
                require(id <= 255,"ECL program ID outside byte range");
                result.next_program = static_cast<std::uint8_t>(id);
                result.exited = true;
                return result;
            }
            case 0x2d:
                require(args[0].type >= 1 && args[0].type <= 3,"Unsupported native ECL call operand");
                host.native_call(static_cast<std::uint16_t>(args[0].value)); break;
            case 1: cursor = branch(args[0]); break;
            case 2:
                require(stack.size() < limits.stack_depth, "ECL stack depth limit exceeded");
                stack.push_back(cursor); cursor = branch(args[0]); break;
            case 0x13:
                require(!stack.empty(), "ECL RETURN with empty stack");
                cursor = stack.back(); stack.pop_back(); break;
            case 3: {
                if (args[0].type >= 0x80 || args[1].type >= 0x80) {
                    const auto left = string(args[0], state, host), right = string(args[1], state, host);
                    state.comparison = left < right ? -1 : left > right ? 1 : 0;
                } else {
                    const auto left = numeric(args[0]), right = numeric(args[1]);
                    state.comparison = left < right ? -1 : left > right ? 1 : 0;
                }
                break;
            }
            case 0x14:
                state.comparison = numeric(args[0]) == numeric(args[1]) && numeric(args[2]) == numeric(args[3]) ? 0 : 1;
                break;
            case 4:
                store(args[2],numeric(args[0]) + numeric(args[1]));
                break;
            case 5: case 6: case 7: {
                require(arithmetic == EclArithmeticDialect::unsigned16,"Arithmetic dialect disabled");
                const auto left = numeric(args[0]) & 65535u, right = numeric(args[1]) & 65535u;
                if (instruction.opcode == 6) require(right != 0,"ECL division by zero");
                const auto value = instruction.opcode == 5 ? right-left :
                    instruction.opcode == 6 ? left/right : left*right;
                store(args[2],value & 65535u);
                break;
            }
            case 8: {
                require(random == EclRandomDialect::byte_upper,"Unsupported VM opcode 8 (random dialect disabled)");
                require(state.random.has_value(),"RNG state unavailable; legacy saves require an explicit new seed");
                const auto upper = numeric(args[0]) & 255u;
                auto candidate = *state.random;
                const auto value = candidate.draw(static_cast<std::uint16_t>(std::min(upper+1,255u)));
                store(args[1],value); // Invalid destinations do not consume the stream.
                state.random = candidate;
                break;
            }
            case 9:
                if (args[0].type >= 0x80) {
                    require(args[1].type == 0x81, "Invalid ECL string destination");
                    const auto value = string(args[0], state, host);
                    const auto address = static_cast<std::uint16_t>(args[1].value);
                    if (!host.write_string(address,value)) state.strings[address] = value;
                } else store(args[1], numeric(args[0]));
                break;
            case 0x2f: {
                const auto value = numeric(args[0]) & numeric(args[1]);
                store(args[2],value);
                state.comparison = value == 0 ? 0 : 1;
                break;
            }
            case 0x2a: {
                auto source = args[0];
                require(source.type == 1 || source.type == 3 || source.type == 5, "Invalid COPY_MEM source");
                const auto offset = numeric(args[1]);
                require(offset <= 65535 && source.value <= 65535 - offset, "COPY_MEM source out of bounds");
                source.value += offset;
                store(args[2], numeric(source));
                break;
            }
            case 0x11: case 0x12: host.text(string(args[0], state, host), instruction.opcode == 0x12); break;
            case 0x16: case 0x17: case 0x18: case 0x19: case 0x1a: case 0x1b: {
                const int cmp = state.comparison;
                const bool conditions[]{cmp == 0, cmp != 0, cmp < 0, cmp > 0, cmp <= 0, cmp >= 0};
                if (!conditions[instruction.opcode - 0x16]) cursor += decode(cursor).size;
                break;
            }
            case 0x25: case 0x26: {
                const auto table = decode_ecl_dispatch_table(code, instruction.offset, dialect, opcodes, entries.header_size);
                const auto selector = numeric(table.selector);
                if (selector >= table.target_offsets.size()) break; // SSI-style fallthrough
                result.dispatches.push_back({instruction.offset, selector, table.target_offsets[selector], table.subroutine});
                if (table.subroutine) {
                    require(stack.size() < limits.stack_depth, "ECL stack depth limit exceeded");
                    stack.push_back(cursor);
                }
                cursor = table.target_offsets[selector];
                break;
            }
            case 0x15: case 0x2b: {
                destination(args[0], state);
                const bool vertical = instruction.opcode == 0x15;
                const std::size_t first = vertical ? 3 : 2;
                std::vector<std::string> choices;
                for (std::size_t i = first; i < args.size(); ++i) choices.push_back(string(args[i], state, host));
                require(!choices.empty(), "Empty ECL menu");
                const auto choice = host.menu(choices, vertical ? string(args[1], state, host) : "", vertical);
                require(choice < choices.size(), "Menu host returned invalid choice");
                store(args[0], static_cast<std::uint32_t>(choice));
                break;
            }
            case 0x0a: {
                require(party_spec != opcodes.end(),"Unsupported VM party opcode");
                const auto index = numeric(args[0]);
                require(index <= 255,"Character index outside byte range");
                host.load_character(static_cast<std::uint8_t>(index));
                break;
            }
            case 0x39:
                host.select_character(string(args[0],state,host));
                break;
            case 0x24: host.combat(state); break;
            case 0x1c:
                require(monsters == EclMonsterDialect::setup_v1,"Monster setup dialect disabled");
                host.clear_monsters(); break;
            case 0x0b: {
                require(monsters == EclMonsterDialect::setup_v1,"Monster setup dialect disabled");
                const auto resource = numeric(args[0]) & 255u, count = numeric(args[1]) & 255u;
                const auto selector = numeric(args[2]) & 255u;
                host.load_monsters({static_cast<std::uint8_t>(resource),static_cast<std::uint8_t>(count),
                    static_cast<std::uint8_t>(selector)});
                break;
            }
            case 0x29: {
                require(encounter.has_value(),"Encounter adapter unavailable");
                destination(args[3],state);
                const auto sprite = numeric(args[0]) & 255u, requested = numeric(args[1]);
                const auto picture = numeric(args[2]) & 255u;
                require(requested <= 2,"Unsupported encounter distance");
                std::array<std::uint8_t,5> behaviors{};
                for (std::size_t i = 0; i < behaviors.size(); ++i) {
                    behaviors[i] = numeric(args[4+i]) & 255u;
                    require(behaviors[i] <= 4,"Unsupported encounter behavior");
                }
                std::array<std::string,3> descriptions{};
                for (std::size_t i = 0; i < descriptions.size(); ++i) descriptions[i] = string(args[9+i],state,host);
                const auto minimum = numeric(args[12]) & 255u, maximum = numeric(args[13]) & 255u;
                EclOperand mode{}; mode.type = 1; mode.value = encounter->view_mode_address;
                const bool dungeon = numeric(mode) != 0;
                const auto visible = host.encounter_distance();
                require(visible <= 2,"Invalid encounter visibility");
                auto distance = static_cast<std::uint8_t>(std::min(requested,std::uint32_t(visible)));
                const auto publish_distance = [&](std::size_t index, std::uint8_t value) {
                    EclOperand output{}; output.type = 1; output.value = encounter->distance_addresses[index];
                    store(output,value);
                };
                publish_distance(0,static_cast<std::uint8_t>(requested)); publish_distance(1,distance);
                const auto show_sprite = [&] { host.sprite_start({static_cast<std::uint8_t>(sprite),distance,
                    static_cast<std::uint8_t>(picture)}); };
                const auto message = [&](std::string_view value) {
                    host.text(value,true);
                    if (!value.empty()) {
                        const std::array<std::string,1> choices{"CONTINUE"};
                        require(host.menu(choices,"",false) == 0,"Invalid encounter continuation choice");
                    }
                };
                const auto movement = [&] {
                    const auto rates = host.party_movement();
                    require(rates[0] <= rates[1],"Invalid party movement range");
                    return rates;
                };
                show_sprite();
                while (true) {
                    require(result.steps < limits.steps,"ECL step limit exceeded"); ++result.steps;
                    std::string_view description;
                    for (unsigned i = 0; i < 3; ++i) if (!descriptions[(distance+i)%3].empty()) {
                        description = descriptions[(distance+i)%3]; break;
                    }
                    message(description);
                    const bool parlay = distance == 0 || !dungeon;
                    const std::array<std::string,4> choices{"COMBAT","WAIT","FLEE",parlay ? "PARLAY" : "ADVANCE"};
                    auto choice = host.menu(choices,"",false);
                    require(choice < choices.size(),"Invalid encounter menu choice");
                    if (choice == 3 && parlay) choice = 4;
                    const auto behavior = behaviors[choice];
                    bool repeat = false;
                    std::uint8_t outcome{};
                    const auto advance = [&] {
                        if (distance) { --distance; publish_distance(1,distance); show_sprite(); }
                        else message("BOTH SIDES WAIT.");
                        repeat = true;
                    };
                    switch (behavior) {
                    case 0: outcome = choice == 2 && movement()[0] >= minimum ? 2 : 1; break;
                    case 1:
                        if (choice == 0) outcome = 1;
                        else if (choice == 1) { message("BOTH SIDES WAIT."); repeat = true; }
                        else if (choice == 2) outcome = 2;
                        else if (choice == 3) advance();
                        else if (distance == 0) outcome = 3;
                        else advance();
                        break;
                    case 2:
                        outcome = choice == 0 && maximum <= movement()[1] ? 1 : 0;
                        store(args[3],outcome);
                        if (!outcome) message("THE MONSTERS FLEE.");
                        break;
                    case 3:
                        if (choice == 0) outcome = 1;
                        else if (choice == 2) outcome = 2;
                        else if (choice == 1 || choice == 3) advance();
                        else if (distance == 0) outcome = 3;
                        else advance();
                        break;
                    case 4:
                        if (choice == 0) outcome = 1;
                        else if (choice == 2) outcome = 2;
                        else if (distance == 0) outcome = 3;
                        else advance();
                        break;
                    }
                    if (repeat) continue;
                    if (behavior != 2) store(args[3],outcome);
                    break;
                }
                break;
            }
            case 0x0e: {
                if (!images_enabled) throw EclDecodeError("Unsupported VM opcode 14");
                const auto id = numeric(args[0]);
                require(id <= 255,"Picture ID outside byte range");
                if (id == 255) host.clear_images();
                else host.picture(static_cast<std::uint8_t>(id));
                break;
            }
            case 0x0c: {
                const auto id = numeric(args[0]), distance = numeric(args[1]), picture = numeric(args[2]);
                require(id <= 255 && distance <= 2 && picture <= 255,"Invalid sprite request");
                host.sprite_start({static_cast<std::uint8_t>(id),static_cast<std::uint8_t>(distance),
                    static_cast<std::uint8_t>(picture)});
                break;
            }
            case 0x0d:
                if (!images_enabled) throw EclDecodeError("Unsupported VM opcode 13");
                host.sprite_advance(); break;
            case 0x31:
                if (!images_enabled) throw EclDecodeError("Unsupported VM opcode 49");
                host.clear_images(); break;
            case 0x37: {
                if (!images_enabled) throw EclDecodeError("Unsupported VM opcode 55");
                std::array<std::uint8_t,3> banks{};
                for (std::size_t i = 0; i < banks.size(); ++i) {
                    const auto id = numeric(args[i]);
                    require(id <= 255,"Wall bank ID outside byte range");
                    banks[i] = static_cast<std::uint8_t>(id);
                }
                host.wall_banks(banks);
                break;
            }
            case 0x21: {
                std::array<std::uint8_t,3> values{};
                for (std::size_t i = 0; i < values.size(); ++i) {
                    const auto value = numeric(args[i]);
                    require(value <= 255,"Map selector outside byte range");
                    values[i] = static_cast<std::uint8_t>(value);
                }
                host.load_area(values);
                break;
            }
            default: throw EclDecodeError("Unsupported VM opcode " + std::to_string(instruction.opcode));
            }
        }
    } catch (const std::exception& error) {
        result.diagnostic = error.what();
        return result;
    }
}
} // namespace goldbox

