            first_menu = true;
            rez = 0;
        } else if rez == menus::MENU_REINIT {
            rez = 0;
        } else if rez == menus::MENU_GREETS {
            st.menus.end();
            crate::intro::greets(sys).await;
            rez = 0;
        }
        apply_audio_cfg(sys, &st.cfg);
