package physics

import (
	"fmt"
	"pinballfantasies/internal/gameplay"
	"pinballfantasies/internal/settings"
)

type EventKind uint8

const (
	EventBumperHit EventKind = iota + 1
	EventSlingshotHit
	EventFlipperHit
	EventTargetHit
	EventDrain
)

type Event struct {
	Kind   EventKind
	Object int
	X, Y   int16
}
type Ball struct {
	X, Y                                     int32
	VX, VY, GX, GY, PixelX, PixelY, Rotation int16
	High, Hold, Lost                         bool
	HitX, HitY                               int16
	CollisionAngle                           uint16
	ContactCount, Material                   uint8
}
type Inputs = gameplay.Controls
type Game struct {
	Configured   bool
	TiltDisabled bool  // FANTASIE/TILTDISABLED; physical TILT0 push still runs.
	FastBall     bool  // FAIRPLAY clears SHIFTKEYS bit2; HI_RES initially sets it.
	TargetRaster int16 // SCREENFORCE2: desired viewport, still smoothed

	PresentationFullTable bool // Render-only host override; never read by simulation or persistence.
	Settings              settings.Config
	ReferenceMode         byte // Historical DOS palette reference; never a native user setting.
	gravity               [][2]int16
	Table                 *Table
	Ball                  Ball
	Flippers              [3]Flipper
	mask12                []byte
	mask22                []byte
	// Optional Party Land consumer, called at the original callback boundaries.
	OnEvent                                   func(Event)
	BeforeLate                                func()       // PF4.5 matrix work finishes VBLANK before late-raster physics.
	ScrollForce                               func() int16 // nil preserves the PF3 camera exactly.
	BeforeTargets                             func()
	AfterTargets                              func(Inputs)
	Raster                                    int16 // original RASTERPOS, 1/16 scanline including SPLH
	Events                                    []Event
	Syncs                                     uint64
	Stopped                                   bool
	pendingBumper                             bool
	pendingEvent                              Event
	indices                                   []byte
	graphicsFrame                             [3]int16
	SpringValid                               bool
	AllowFlip, Tilted, tiltLatched            bool
	TiltCounter                               uint16
	ScreenPosition, ScreenSpeed, ScreenOffset int16
	SpringPosition                            uint8
	SpringGraphics                            []byte
}

func New(t *Table) *Game {
	g := &Game{Table: t, TargetRaster: -1, Settings: settings.Legacy(), gravity: append([][2]int16(nil), t.gravity...), Flippers: t.Flippers, mask12: append([]byte(nil), t.mask12...), mask22: append([]byte(nil), t.mask22...), Raster: (259 + 33) * 16}
	g.indices = append([]byte(nil), t.Initial.Playfield.Indices...)
	g.SpringValid = true
	g.AllowFlip = true
	x, y := int16(t.start.X), int16(t.start.Y)
	g.Ball = Ball{X: int32(x) * 1024, Y: int32(y) * 1024, VX: 10, GY: 8, PixelX: x, PixelY: y}
	for i := range g.Flippers {
		g.copyFlipper(i)
	}
	return g
}

// Release is the high-resolution SPRINGUP arithmetic. Charge is the original
// springpos byte (0..32); jitter is SLUMP_COUNTERN's low eight bits, supplied
// explicitly so replay never depends on host timing or a random generator.
func (g *Game) Release(charge, jitter uint8) {
	if charge == 0 || charge > 32 || g.Ball.Lost || !g.SpringValid {
		return
	}
	g.Ball.VX = 0
	g.Ball.VY = -166*int16(charge) - int16(jitter)
	g.Ball.Rotation = int16(jitter & 15)
	// SPRING_VALID is initially true; later table-rule callbacks are events.
}

// Sync reproduces a high-resolution gameplay interrupt pair: VBLANK executes
// two sc_program passes, then DO_PHYSICS; late raster executes one pass.
// One step always checks collision, resolves it, updates flipper state, moves
// the ball, then copies any overlapping flipper mask.
func (g *Game) Sync(input Inputs) error { return g.sync(input, nil) }

// SyncWithGate is an internal candidate boundary. Admission is before the
// entire named consumer; accepting an aggregate accepts all of its effects.
// The caller owns sticky failure and must not re-enter after a rejected gate.
// Ordinary hosts continue to call Sync, with no admission policy.
func (g *Game) SyncWithGate(input Inputs, gate func(producer, consumer string) error) error {
	if gate == nil {
		return fmt.Errorf("candidate consumption gate is required")
	}
	if err := gate("candidate", "physics.Sync"); err != nil {
		return err
	}
	return g.sync(input, gate)
}

func (g *Game) sync(input Inputs, gate func(string, string) error) error {
	admit := func(producer, consumer string) error {
		if gate != nil {
			return gate(producer, consumer)
		}
		return nil
	}
	g.Events = g.Events[:0]
	if g.Stopped {
		return nil
	}
	for i := 0; i < 2; i++ {
		if err := admit("physics.Sync", "physics.step"); err != nil {
			return err
		}
		if err := g.step(input); err != nil {
			return err
		}
	}
	if g.pendingBumper {
		if err := admit("pendingBumper", "OnEvent"); err != nil {
			return err
		}
		g.Events = append(g.Events, g.pendingEvent)
		g.pendingBumper = false
		if g.OnEvent != nil {
			g.OnEvent(g.pendingEvent)
		}
	}
	if g.TiltCounter > 0 {
		g.TiltCounter--
	}
	if err := admit("physics.Sync", "checkRamps/checkLevels"); err != nil {
		return err
	}
	g.checkRamps()
	g.checkLevels()
	if g.Ball.Lost {
		if err := admit("Ball.Lost", "drain/OnEvent"); err != nil {
			return err
		}
		g.Stopped = true
		e := Event{Kind: EventDrain, X: g.Ball.PixelX, Y: g.Ball.PixelY}
		g.Events = append(g.Events, e)
		if g.OnEvent != nil {
			g.OnEvent(e)
		}
		return nil
	}
	if g.BeforeTargets != nil {
		if err := admit("physics.Sync", "BeforeTargets"); err != nil {
			return err
		}
		g.BeforeTargets()
	}
	if err := admit("physics.Sync", "checkSpringAndTargets/OnEvent"); err != nil {
		return err
	}
	g.checkSpringAndTargets()
	if g.AfterTargets != nil {
		if err := admit("physics.Sync", "AfterTargets"); err != nil {
			return err
		}
		g.AfterTargets(input)
	}
	if g.BeforeLate != nil {
		if err := admit("physics.Sync", "BeforeLate"); err != nil {
			return err
		}
		g.BeforeLate()
	}
	if err := admit("physics.Sync", "scroll/ScrollForce"); err != nil {
		return err
	}
	g.scroll()
	lateSteps := 1
	if g.FastBall {
		lateSteps = 2
	}
	for i := 0; i < lateSteps; i++ {
		if err := admit("physics.Sync", "physics.step"); err != nil {
			return err
		}
		if err := g.step(input); err != nil {
			return err
		}
	}
	g.Syncs++
	return nil
}

func (g *Game) step(input Inputs) error {
	if !g.Ball.Hold {
		if c, ok := g.collision(); ok {
			if err := g.respond(c); err != nil {
				return err
			}
		}
	}
	g.push(input.Tilt)
	g.moveFlippers(input)
	if !g.Ball.Hold {
		b := &g.Ball
		b.Y += int32(b.VY)
		y, err := divide(b.Y, 1024)
		if err != nil {
			return err
		}
		b.PixelY = y
		if b.PixelY >= 576 {
			b.Lost = true
		}
		b.X += int32(b.VX)
		x, err := divide(b.X, 1024)
		if err != nil {
			return err
		}
		b.PixelX = x
		b.VY += b.GY
		b.VX += b.GX
		if b.Rotation > 0 {
			b.Rotation -= 2
			if b.Rotation <= 0 {
				b.Rotation = 0
			}
		} else if b.Rotation < 0 {
			b.Rotation += 2
			if b.Rotation >= 0 {
				b.Rotation = 0
			}
		}
	}
	for i, f := range g.Flippers {
		if f.Bounds.contains(g.Ball.PixelX, g.Ball.PixelY) {
			g.copyFlipper(i)
		}
	}
