}

func divide(n int32, d int16) (int16, error) {
	if d == 0 {
		return 0, fmt.Errorf("original physics IDIV divisor zero")
	}
	q := int64(n) / int64(d)
	if q < -32768 || q > 32767 {
		return 0, fmt.Errorf("original physics IDIV quotient overflow: %d / %d", n, d)
	}
