}
func clamp(v int16) int16 {
	if v < -4100 {
		return -4100
	}
	if v > 4100 {
		return 4100
	}
	return v
}
func highProduct(a, b int16) int16 { return int16((int32(a) * int32(b)) >> 16) }

func (g *Game) moveFlippers(input Inputs) {
